TOPICS=[]
QUESTIONS=[]
def T(lesson, slug, title, notebook, cells, definition, detail, example, trap, prompt, rubric, formula=''):
    topic={'id':slug,'lesson':lesson,'title':title,'source':{'path':f'lesson_{lesson}/{notebook}.ipynb','cells':cells},
           'definition':definition,'detail':detail,'example':example,'trap':trap,'formula':formula}
    TOPICS.append(topic)
    QUESTIONS.append({'id':slug+'-explain','lesson':lesson,'topic':slug,'type':'open','level':'reason',
                      'prompt':prompt,'answer':definition+'\n\n'+detail,'example':example,'rubric':rubric,'source':topic['source']})
    return topic

